USE mitra;
CREATE TABLE IF NOT EXISTS reports(id BIGINT UNSIGNED PRIMARY KEY,reporter_id BIGINT UNSIGNED NOT NULL,target_type VARCHAR(32) NOT NULL,target_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(120) NOT NULL,status ENUM('open','reviewing','resolved','rejected') NOT NULL DEFAULT 'open',created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(reporter_id) REFERENCES users(id),INDEX idx_reports_status_created(status,created_at DESC));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT UNSIGNED PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,type VARCHAR(32) NOT NULL,actor_id BIGINT UNSIGNED NULL,post_id BIGINT UNSIGNED NULL,read_at TIMESTAMP(6) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_notifications_user_created(user_id,created_at DESC,id DESC));
